from rest_framework import serializers
from .models import Invoice, InvoiceLineItem

class LineItemSerializer(serializers.ModelSerializer):
    id = serializers.IntegerField(required=False)

    class Meta:
        model = InvoiceLineItem
        fields = ['id', 'description', 'unit_price', 'quantity']

class BatchInvoiceUpdateSerializer(serializers.ModelSerializer):
    line_items = LineItemSerializer(many=True)

    class Meta:
        model = Invoice
        fields = ['invoice_number', 'line_items']

    def update(self, instance, validated_data):
        items_data = validated_data.pop('line_items')
        for item_data in items_data:
            item_id = item_data.get('id')
            if item_id:
                # Restrict line item update to items belonging strictly to the current invoice
                InvoiceLineItem.objects.filter(id=item_id, invoice=instance).update(
                    description=item_data.get('description'),
                    unit_price=item_data.get('unit_price'),
                    quantity=item_data.get('quantity')
                )
        return super().update(instance, validated_data)
